namespace ghidra.app.plugin.core.debug.gui.model;






public interface ColorsModified<P> where P : JComponent {

	Color getDiffForeground(P p);

	Color getDiffSelForeground(P p);

	Color getForeground(P p);

	Color getSelForeground(P p);

	Color getForegroundFor(P p, bool isModified, bool isSelected) {
		return isModified ? isSelected ? getDiffSelForeground(p) : getDiffForeground(p)
				: isSelected ? getSelForeground(p) : getForeground(p);
	}

	interface InTable : ColorsModified<JTable> {
		/* @Override */
		Color getForeground(JTable table) {
			return table.getForeground();
		}

		/* @Override */
		Color getSelForeground(JTable table) {
			return table.getSelectionForeground();
		}
	}

	interface InTree : ColorsModified<JTree>, TreeCellRenderer {

		Color getTextNonSelectionColor();

		Color getTextSelectionColor();

		/* @Override */
		Color getForeground(JTree tree) {
			return getTextNonSelectionColor();
		}

		/* @Override */
		Color getSelForeground(JTree tree) {
			return getTextSelectionColor();
		}
	}
}
